def transform(grid):
    new_grid = []
    for row_idx, row in enumerate(grid):
        new_row = []
        for col_idx, cell in enumerate(row):
            # Background is 2
            # Pattern: 
            # - 5s in top-left region (rows 0-2, cols 0-4) become 6s
            # - 8s in left-middle region (rows 8-13, cols 0-4) become 6s
            # - Other colors stay same if not in transform region
            if cell == 5 and row_idx <= 2 and col_idx <= 13:
                new_row.append(6)
            elif cell == 8 and row_idx >= 8 and col_idx <= 4:
                new_row.append(6)
            else:
                new_row.append(cell)
        new_grid.append(new_row)
    return new_grid
